class Solution {
    fun maxSubarraySumCircular(nums:IntArray):Int{
        var total=nums[0];
        var currentMax=nums[0];
        var bestMax=nums[0];
        var currentMin=nums[0];
        var bestMin=nums[0];
        for(i in 1 until nums.size){
            val value=nums[i];
            currentMax=maxOf(value,currentMax+value);
            bestMax=maxOf(bestMax,currentMax);
            currentMin=minOf(value,currentMin+value);
            bestMin=minOf(bestMin,currentMin);
            total+=value
        };
        return if(bestMax<0)bestMax else maxOf(bestMax,total-bestMin)
    }
}

